questionvariables.text:
/*Randomisation of the coefficients of the first function*/
aa: rand_with_prohib(-5,5,[0]);
bb: rand_with_prohib(-5,5,[0]);
cc: rand_with_prohib(-5,5,[0]);
dd: rand_with_prohib(-5,5,[0]);
ee: rand_with_prohib(-7,7,[0]);
ff:rand_with_prohib(-5,5,[0]);
/*Defining the first randomised function*/
f_1: aa*x^3*z^2+bb*x*y^5*z=cc*x^2+dd*y^3;
/*Steps of expression of partial of z w.r.t x*/
ta_1a: diff(cc*x^2+dd*y^3,x)-diff(aa*x^3,x)*z^2-diff(bb*x*y^5,x)*z; /*expression of the numerator*/
ta_1b: aa*x^3*diff(z^2,z)+bb*x*y^5*diff(z,z); /*expression of the denominator*/
ta_1: ta_1a/ta_1b; /*partial of z w.r.t x*/
/*Steps of expression of partial of z w.r.t y*/
ta_2a: diff(cc*x^2+dd*y^3,y)-diff(aa*x^3,y)*z^2-diff(bb*x*y^5,y)*z; /*expression of the numerator*/
ta_2b: aa*x^3*diff(z^2,z)+bb*x*y^5*diff(z,z); /*expression of the denominator*/
ta_2: ta_2a/ta_2b; /*partial of z w.r.t y*/
/*Defining the second randomised function*/
f_2: aa*x^2*sin(bb*y+cc*z)=ff+dd*y*cos(ee*z*x);
ta_3a:-dd*y*diff(ee*x,x)*z*sin(ee*z*x)-diff(aa*x^2,x)*sin(bb*y+cc*z);
ta_3b: dd*y*ee*x*sin(ee*z*x)+aa*x^2*diff(sin(bb*y+cc*z),z); 
ta_3: ta_3a/ta_3b;
ta_4a:-aa*x^2*bb*cos(bb*y+cc*z)-diff(aa*x^2,y)*sin(bb*y+cc*z)+diff(dd*y,y)*cos(ee*z*x)-dd*y*diff(ee*x,y)*z*sin(ee*z*x);
ta_4b: dd*y*ee*x*sin(ee*z*x)+aa*x^2*cc*cos(bb*y+cc*z);
ta_4: ta_4a/ta_4b;
